<?php $this->layout('default'); use Moves\Services\CmsQuery as Q; use Moves\Services\PlatformDirectory as D; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = D::companies($filters, V::queryPage()); $st = ['active' => 'Ativa', 'inactive' => 'Inativa']; $n = static fn (string $s): string => (string) Q::value($s); ?>
<?= V::kpis([['building', 'Empresas', $n('SELECT COUNT(*) FROM organizations'), 'cadastradas'], ['check', 'Ativas', $n("SELECT COUNT(*) FROM organizations WHERE status='active'"), 'em operação'], ['clock', 'Inativas', $n("SELECT COUNT(*) FROM organizations WHERE status='inactive'"), 'sem operação'], ['repeat', 'Com assinatura', $n("SELECT COUNT(DISTINCT organization_id) FROM subscriptions WHERE organization_id IS NOT NULL AND status<>'canceled'"), 'contratos vigentes']]) ?>
<section class="cms-list"><?= V::listHead('Lista de empresas', $result['total'] . ' registro(s)', V::searchForm('Buscar empresa ou responsável', ['status' => [$filters['status'], ['' => 'Todas'] + $st, 'Situação']])) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma empresa encontrada.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Empresas"><table><thead><tr><th>Empresa</th><th class="num">Membros</th><th>Plano</th><th>Status</th><th class="cms-th-actions">Ações</th></tr></thead><tbody><?php foreach ($result['rows'] as $c): ?><tr><td><div class="cms-cell"><i class="cms-thumb"><?= V::icon('building') ?></i><div><a href="/empresas/<?= (int) $c['id'] ?>"><?= V::e($c['trade_name'] ?: $c['name']) ?></a><br><small><?= V::e($c['owner_email']) ?></small></div></div></td><td class="num"><?= (int) $c['members_count'] ?></td><td><?= V::e($c['plan_name'] ?? '—') ?></td><td><?= V::badge($c['status'], $st[$c['status']] ?? $c['status']) ?></td><td class="cms-td-actions"><?= V::iconLink('/empresas/' . (int) $c['id'], 'Abrir', 'eye') ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></section>
